cat > /workspace/src/main.rs << 'RUST_EOF'
use std::env;
use std::ffi::{OsStr, OsString};
use std::fs;
use std::io::{self, Write};
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

const VERSION: &str = "0.2.18";
const BAR_WIDTH: usize = 32;
const NAME_FIELD_WIDTH: usize = 26;
const TREE_INDENT: usize = 3;
const MAX_SHADE_DEPTH: usize = 3; // Max number of ancestor shades

#[derive(Debug, Clone)]
struct Opts {
    depth: usize,
    aggr: Option<u64>,   // threshold in bytes; None means no aggregation
    usage: bool,
    bytes: bool,
    files_only: bool,
    excludes: Vec<OsString>,
    no_hidden: bool,
    ascii: bool,
    paths: Vec<PathBuf>,
}

impl Default for Opts {
    fn default() -> Self {
        Self {
            depth: 1,
            aggr: None,
            usage: false,
            bytes: false,
            files_only: false,
            excludes: Vec::new(),
            no_hidden: false,
            ascii: false,
            paths: Vec::new(),
        }
    }
}

fn print_usage(prog: &str) {
    println!("Usage: {} [options] <path> [<path>..]", prog);
    println!();
    println!("Options:");
    println!("    -d, --depth [DEPTH] show directories up to depth N (def 1)");
    println!("    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)");
    println!("    -s, --summary       equivalent to -da, or -d1 -a1M");
    println!("    -u, --usage         report real disk usage instead of file size");
    println!("    -b, --bytes         print sizes in bytes");
    println!("    -f, --files-only    skip directories for a fast local overview");
    println!("    -x, --exclude NAME  exclude matching files or directories");
    println!("    -H, --no-hidden     exclude hidden files");
    println!("    -A, --ascii         ASCII characters only, no colors");
    println!("    -h, --help          show help");
    println!("    -v, --version       print version number");
}

fn parse_size(s: &str) -> Option<u64> {
    if s.is_empty() {
        return None;
    }
    let bytes = s.as_bytes();
    let mut num_end = 0;
    while num_end < bytes.len() && bytes[num_end].is_ascii_digit() {
        num_end += 1;
    }
    if num_end == 0 {
        return None;
    }
    let num_str = &s[..num_end];
    let num: u64 = num_str.parse().ok()?;
    let rest = &s[num_end..];
    // Allow trailing whitespace
    let rest_trimmed = rest.trim_end();
    let mult: u64 = match rest_trimmed {
        "" => 1,
        "k" | "K" => 1024,
        "m" | "M" => 1024 * 1024,
        "g" | "G" => 1024 * 1024 * 1024,
        "t" | "T" => 1024u64 * 1024 * 1024 * 1024,
        s if s.len() == 1 => 1, // any single char allowed, acts like bytes
        _ => return None,
    };
    Some(num.saturating_mul(mult))
}

fn parse_depth(s: &str) -> Option<usize> {
    s.parse::<usize>().ok()
}

// Parse CLI arguments. Returns Ok((opts, prog_name)) or Err(exit_code)
fn parse_args(argv: Vec<String>) -> Result<Opts, (i32, Option<String>)> {
    let prog = argv.first().cloned().unwrap_or_else(|| "dutree".to_string());
    let mut opts = Opts::default();
    let mut iter = argv.into_iter().skip(1).peekable();
    let mut got_d = false;
    let mut got_a = false;
    // Aggregation default if -s is given
    let default_aggr: u64 = 1024 * 1024;

    while let Some(a) = iter.next() {
        if a == "--" {
            // Remaining args are paths
            while let Some(p) = iter.next() {
                opts.paths.push(PathBuf::from(p));
            }
            break;
        }
        if let Some(rest) = a.strip_prefix("--") {
            // Long option
            let (name, value) = match rest.find('=') {
                Some(pos) => (&rest[..pos], Some(&rest[pos + 1..])),
                None => (rest, None),
            };
            match name {
                "depth" => {
                    if let Some(v) = value {
                        got_d = true;
                        if let Some(d) = parse_depth(v) {
                            opts.depth = d;
                        }
                    } else {
                        got_d = true;
                    }
                }
                "aggr" => {
                    if let Some(v) = value {
                        match parse_size(v) {
                            Some(sz) => {
                                opts.aggr = Some(sz);
                                got_a = true;
                            }
                            None => {
                                eprintln!("invalid argument '{}'", v);
                                return Err((1, None));
                            }
                        }
                    } else {
                        opts.aggr = Some(default_aggr);
                        got_a = true;
                    }
                }
                "summary" => {
                    got_d = true;
                    got_a = true;
                    opts.depth = 1;
                    opts.aggr = Some(default_aggr);
                }
                "usage" => opts.usage = true,
                "bytes" => opts.bytes = true,
                "files-only" => opts.files_only = true,
                "exclude" => {
                    if let Some(v) = value {
                        opts.excludes.push(OsString::from(v));
                    } else if let Some(v) = iter.next() {
                        opts.excludes.push(OsString::from(v));
                    } else {
                        eprintln!("missing argument for --exclude");
                        return Err((1, None));
                    }
                }
                "no-hidden" => opts.no_hidden = true,
                "ascii" => opts.ascii = true,
                "help" => {
                    print_usage(&prog);
                    return Err((0, None));
                }
                "version" => {
                    return Err((0, Some(format!("dutree version {}", VERSION))));
                }
                _ => {
                    print_usage(&prog);
                    eprintln!("Unrecognized option: '{}'", name);
                    return Err((1, None));
                }
            }
        } else if a.starts_with('-') && a.len() > 1 {
            // Short option(s). May be combined like -Af
            let chars: Vec<char> = a[1..].chars().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let c = chars[ci];
                match c {
                    'd' => {
                        got_d = true;
                        // If there are more chars in this option, they are the value
                        if ci + 1 < chars.len() {
                            let val: String = chars[ci + 1..].iter().collect();
                            if let Some(d) = parse_depth(&val) {
                                opts.depth = d;
                            }
                            ci = chars.len();
                        } else {
                            // Peek next arg
                            if let Some(next) = iter.peek() {
                                if !next.starts_with('-') {
                                    let val = iter.next().unwrap();
                                    if let Some(d) = parse_depth(&val) {
                                        opts.depth = d;
                                    }
                                    // If not parseable, silently ignore (keep default)
                                }
                            }
                            ci += 1;
                        }
                    }
                    'a' => {
                        if ci + 1 < chars.len() {
                            let val: String = chars[ci + 1..].iter().collect();
                            match parse_size(&val) {
                                Some(sz) => {
                                    opts.aggr = Some(sz);
                                    got_a = true;
                                }
                                None => {
                                    eprintln!("invalid argument '{}'", val);
                                    return Err((1, None));
                                }
                            }
                            ci = chars.len();
                        } else {
                            // Peek next arg
                            let mut consumed = false;
                            if let Some(next) = iter.peek() {
                                if !next.starts_with('-') {
                                    let val = iter.next().unwrap();
                                    match parse_size(&val) {
                                        Some(sz) => {
                                            opts.aggr = Some(sz);
                                            got_a = true;
                                        }
                                        None => {
                                            eprintln!("invalid argument '{}'", val);
                                            return Err((1, None));
                                        }
                                    }
                                    consumed = true;
                                }
                            }
                            if !consumed {
                                opts.aggr = Some(default_aggr);
                                got_a = true;
                            }
                            ci += 1;
                        }
                    }
                    's' => {
                        got_d = true;
                        got_a = true;
                        opts.depth = 1;
                        opts.aggr = Some(default_aggr);
                        ci += 1;
                    }
                    'u' => { opts.usage = true; ci += 1; }
                    'b' => { opts.bytes = true; ci += 1; }
                    'f' => { opts.files_only = true; ci += 1; }
                    'x' => {
                        // Always takes an argument
                        if ci + 1 < chars.len() {
                            let val: String = chars[ci + 1..].iter().collect();
                            opts.excludes.push(OsString::from(val));
                            ci = chars.len();
                        } else if let Some(v) = iter.next() {
                            opts.excludes.push(OsString::from(v));
                            ci += 1;
                        } else {
                            eprintln!("missing argument for -x");
                            return Err((1, None));
                        }
                    }
                    'H' => { opts.no_hidden = true; ci += 1; }
                    'A' => { opts.ascii = true; ci += 1; }
                    'h' => {
                        print_usage(&prog);
                        return Err((0, None));
                    }
                    'v' => {
                        return Err((0, Some(format!("dutree version {}", VERSION))));
                    }
                    _ => {
                        print_usage(&prog);
                        eprintln!("Unrecognized option: '{}'", c);
                        return Err((1, None));
                    }
                }
            }
        } else {
            opts.paths.push(PathBuf::from(a));
        }
    }
    // Suppress unused warnings
    let _ = got_d;
    let _ = got_a;
    Ok(opts)
}

// Tree node
#[derive(Debug)]
struct Node {
    name: OsString,
    size: u64,
    children: Vec<Node>,
    aggregated: bool,
}

impl Node {
    fn new_file(name: OsString, size: u64) -> Self {
        Self { name, size, children: Vec::new(), aggregated: false }
    }
}

fn size_for_entry(meta: &fs::Metadata, usage: bool) -> u64 {
    if usage {
        (meta.blocks() as u64) * 512
    } else {
        meta.len()
    }
}

fn is_hidden(name: &OsStr) -> bool {
    let b = name.as_bytes();
    !b.is_empty() && b[0] == b'.'
}

fn build_node(path: &Path, depth_limit: usize, opts: &Opts, current_depth: usize) -> Option<Node> {
    // Use symlink_metadata (lstat) to not follow symlinks for size
    let meta = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => return None,
    };
    let name = path.file_name().map(OsString::from).unwrap_or_else(|| OsString::from(path));

    if opts.excludes.iter().any(|x| x == &name) {
        return None;
    }
    if opts.no_hidden && is_hidden(&name) {
        return None;
    }

    if meta.is_dir() && !meta.file_type().is_symlink() {
        if opts.files_only {
            return None;
        }
        let mut total_size = meta.len(); // dir's own size
        if opts.usage {
            total_size = (meta.blocks() as u64) * 512;
        }
        let mut children: Vec<Node> = Vec::new();

        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                let ent_path = entry.path();
                if let Some(child) = build_node(&ent_path, depth_limit, opts, current_depth + 1) {
                    total_size += child.size;
                    children.push(child);
                }
            }
        }

        // Sort children by size descending
        children.sort_by(|a, b| b.size.cmp(&a.size));

        // Apply aggregation
        if let Some(thresh) = opts.aggr {
            let mut kept: Vec<Node> = Vec::new();
            let mut agg_size: u64 = 0;
            let mut has_agg = false;
            for c in children {
                if c.size < thresh {
                    agg_size += c.size;
                    has_agg = true;
                } else {
                    kept.push(c);
                }
            }
            if has_agg && agg_size > 0 {
                kept.push(Node {
                    name: OsString::from("<aggregated>"),
                    size: agg_size,
                    children: Vec::new(),
                    aggregated: true,
                });
            }
            children = kept;
        }

        // Truncate children if past depth limit
        // current_depth is the depth of this directory
        // children are at depth current_depth + 1
        // We show nodes up to `depth_limit` below the root
        // The root is at depth 0 (for single path) or depth 1 (for collection mode).
        // We'll handle depth trimming in the caller.

        // Actually: prune children if (child_depth_from_root) > depth_limit
        // depth_limit semantics: show directories up to depth N (def 1).
        // In tests, -d 1 shows root + immediate children; -d 2 shows root + children + grandchildren.
        // For files, they're still shown even past depth (at depth N, files are shown).
        // Actually no, looking at -d 1 output on test1: shows children (big.bin, sub1, etc.) but sub1's children aren't shown.
        // So depth limit N = show up to N levels deep (root=level 0, direct children=level 1).
        // At depth limit N, level N items are shown, but their children aren't expanded.

        if current_depth >= depth_limit {
            for c in children.iter_mut() {
                c.children.clear();
            }
        }

        return Some(Node {
            name,
            size: total_size,
            children,
            aggregated: false,
        });
    } else {
        // File or symlink
        let size = size_for_entry(&meta, opts.usage);
        return Some(Node::new_file(name, size));
    }
}

fn format_size(size: u64, bytes_mode: bool) -> String {
    if bytes_mode {
        return format!("{} B", size);
    }
    if size < 1024 {
        return format!("{} B", size);
    }
    let units = ["KiB", "MiB", "GiB", "TiB"];
    let mut value = size as f64 / 1024.0;
    let mut unit_idx = 0;
    while unit_idx < units.len() - 1 && value >= 1024.0 {
        value /= 1024.0;
        unit_idx += 1;
    }
    format!("{:.2} {}", value, units[unit_idx])
}

// Compute bar width: max(0, floor((size * (parent_width + 1) - parent_size) / parent_size))
// For top level: parent_width = 32, parent_size = max_sibling_size.
// For nested: parent_width = parent's own bar width, parent_size = parent's size.
fn compute_bar_width(size: u64, parent_width: usize, parent_size: u64) -> usize {
    if parent_size == 0 || size == 0 {
        return 0;
    }
    // Use 128-bit to avoid overflow
    let num = (size as u128) * ((parent_width as u128) + 1);
    if num <= parent_size as u128 {
        return 0;
    }
    let w = ((num - parent_size as u128) / (parent_size as u128)) as usize;
    if w > parent_width { parent_width } else { w }
}

// Display info for each node to render
struct DisplayInfo {
    depth: usize,                        // 0 = root, 1 = top children, etc.
    name: String,                        // truncated/padded name
    bar_own_width: usize,                // own bar width
    // List of ancestor bar widths in order from outermost to this item's parent
    // Used to render shade regions
    ancestor_widths: Vec<usize>,
    size: u64,
    percent: u64,                        // percentage of parent
    tree_prefix: String,                 // like "│  ├─ " or "   └─ " or "├─ "
    last_in_parent: bool,
    is_root: bool,                       // if true, no bar shown
}

fn render_bar(
    own_width: usize,
    ancestor_widths: &[usize],
    ascii: bool,
) -> String {
    // Total bar: 33 chars (1 leading space + 32 bar chars)
    let mut out = String::new();
    out.push(' ');
    // Build array of 32 characters
    let mut bar: Vec<char> = vec![' '; BAR_WIDTH];

    // We need to figure out the shade regions.
    // Widths: ancestor_widths[0] is outermost (widest), descending to ancestor_widths[last],
    // then own_width (smallest).
    // Each ancestor's shade region = ancestor's own width minus next-level's own width.
    // We render using shades ░, ▒, ▓ for ancestors 1, 2, 3.
    // If more than 3 ancestors, the deepest ancestors (closest to item) are "merged" into the item's own (display as █).
    // Specifically, we use only the OUTERMOST (up to 3) ancestors as shades,
    // and everything from the 4th ancestor down (including item's own) is rendered as █.

    let n = ancestor_widths.len();
    let (shade_widths, merged_own_width): (Vec<usize>, usize) = if n <= MAX_SHADE_DEPTH {
        (ancestor_widths.to_vec(), own_width)
    } else {
        // Take outermost MAX_SHADE_DEPTH
        // The rest collapse into own_width (we use the widest of them)
        let shades = ancestor_widths[..MAX_SHADE_DEPTH].to_vec();
        // The merged own = ancestor_widths[MAX_SHADE_DEPTH] (the depth-4 ancestor's own width)
        // This is the widest of the "merged" group.
        let merged = ancestor_widths[MAX_SHADE_DEPTH];
        (shades, merged)
    };

    // Render from RIGHT to LEFT:
    // - Rightmost merged_own_width chars: █
    // - Before that, for each shade (in reverse), shade_width - next_inner_width chars with shade.

    let shade_chars = if ascii {
        ['#', '#', '#']
    } else {
        ['░', '▒', '▓']
    };
    let full_char = if ascii { '#' } else { '█' };

    // Position from the right: fill own first
    // All bars right-anchored ending at position BAR_WIDTH-1.

    // Start: rightmost is position BAR_WIDTH-1. Fill merged_own_width chars with full.
    let mut filled_width = 0usize;
    for _ in 0..merged_own_width {
        if filled_width < BAR_WIDTH {
            bar[BAR_WIDTH - 1 - filled_width] = full_char;
            filled_width += 1;
        }
    }

    // Now fill shades from innermost to outermost
    let mut inner_width = merged_own_width;
    for (i, &outer_width) in shade_widths.iter().enumerate().rev() {
        // Width of this shade's visible region = outer_width - inner_width
        if outer_width > inner_width {
            let region_width = outer_width - inner_width;
            let ch = shade_chars[i];
            for _ in 0..region_width {
                if filled_width < BAR_WIDTH {
                    bar[BAR_WIDTH - 1 - filled_width] = ch;
                    filled_width += 1;
                }
            }
        }
        inner_width = outer_width;
    }

    for c in &bar {
        out.push(*c);
    }
    out
}

fn visible_width_of_str(s: &str) -> usize {
    // Count chars (approximate; assumes no wide chars in names)
    s.chars().count()
}

fn truncate_name(name: &str, max_width: usize) -> String {
    if visible_width_of_str(name) <= max_width {
        name.to_string()
    } else {
        name.chars().take(max_width).collect::<String>()
    }
}

// Render the tree, printing to stdout
fn render_node(
    node: &Node,
    depth: usize,
    is_last: bool,
    prefix_chain: &mut Vec<bool>, // true = last in parent (use spaces); false = non-last (use │  )
    ancestor_widths: &mut Vec<usize>,
    parent_size: u64,
    parent_bar_width: usize,
    opts: &Opts,
    out: &mut String,
    is_root: bool,
) {
    let ascii = opts.ascii;
    if is_root {
        // Header: [ name size ]
        out.push_str(&format!("[ {} {} ]\n", node.name.to_string_lossy(), format_size(node.size, opts.bytes)));
        // Render children
        let children = &node.children;
        if children.is_empty() {
            return;
        }
        // For root-level children, the "parent" for bar scaling is a virtual thing:
        // parent_width = 32, parent_size = max_sibling_size
        let max_sib = children.iter().map(|c| c.size).max().unwrap_or(1);
        for (i, child) in children.iter().enumerate() {
            let last = i == children.len() - 1;
            prefix_chain.push(last);
            render_node(child, 1, last, prefix_chain, &mut Vec::new(), max_sib, BAR_WIDTH, opts, out, false);
            prefix_chain.pop();
        }
        return;
    }

    // Build tree prefix
    let mut prefix = String::new();
    // All but the last element of prefix_chain (which is THIS node's is_last) determine the ancestor prefix
    if prefix_chain.len() > 0 {
        for i in 0..prefix_chain.len() - 1 {
            if prefix_chain[i] {
                prefix.push_str("   ");
            } else {
                prefix.push_str("│  ");
            }
        }
        if is_last {
            prefix.push_str("└─ ");
        } else {
            prefix.push_str("├─ ");
        }
    }

    let prefix_width = visible_width_of_str(&prefix);
    let name_str = node.name.to_string_lossy().to_string();
    let name_space = NAME_FIELD_WIDTH.saturating_sub(prefix_width);
    // Name must fit in (name_space - 1) chars (1 trailing space always)
    let name_truncated = if name_space > 0 {
        let max_name_len = name_space.saturating_sub(1);
        truncate_name(&name_str, max_name_len)
    } else {
        String::new()
    };
    let name_padding = name_space.saturating_sub(visible_width_of_str(&name_truncated));

    // Compute own bar width
    let own_width = compute_bar_width(node.size, parent_bar_width, parent_size);

    // Build ancestor widths for rendering
    // ancestor_widths param contains widths of outer ancestors (in order from outermost to item's direct parent).
    // For this node to render, we pass it as ancestor_widths.

    // Render bar
    let bar_str = render_bar(own_width, ancestor_widths, ascii);

    // Percentage
    let pct: u64 = if parent_size == 0 { 0 } else {
        // Use saturating math
        let v = (node.size as u128) * 100 / (parent_size as u128);
        v as u64
    };

    // Size formatting
    let size_str = format_size(node.size, opts.bytes);

    // Print line
    out.push_str(&prefix);
    out.push_str(&name_truncated);
    for _ in 0..name_padding {
        out.push(' ');
    }
    out.push('│');
    out.push_str(&bar_str);
    out.push('│');
    out.push_str(&format!("{:>4}%{:>14}", pct, size_str));
    out.push('\n');

    // Recurse into children
    if !node.children.is_empty() {
        // This node's children are rendered with this node as parent.
        // parent_size = node.size
        // parent_bar_width = own_width
        // ancestor_widths for child = ancestor_widths + [own_width]
        ancestor_widths.push(own_width);
        for (i, child) in node.children.iter().enumerate() {
            let last = i == node.children.len() - 1;
            prefix_chain.push(last);
            render_node(child, depth + 1, last, prefix_chain, ancestor_widths, node.size, own_width, opts, out, false);
            prefix_chain.pop();
        }
        ancestor_widths.pop();
    }
}

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let opts = match parse_args(argv) {
        Ok(o) => o,
        Err((code, msg)) => {
            if let Some(m) = msg {
                println!("{}", m);
            }
            return ExitCode::from(code as u8);
        }
    };

    // Determine paths
    let paths = if opts.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        opts.paths.clone()
    };

    // Validate paths exist
    for p in &paths {
        match fs::symlink_metadata(p) {
            Ok(_) => {}
            Err(_) => {
                println!("path {} doesn't exist", p.display());
                return ExitCode::from(1);
            }
        }
    }

    // Build root node
    let depth_limit = opts.depth;

    let root_node: Node = if paths.len() == 1 {
        // Single path: root is that path
        match build_node(&paths[0], depth_limit, &opts, 0) {
            Some(n) => n,
            None => {
                // Empty result - create a placeholder
                let name = paths[0].file_name().map(OsString::from).unwrap_or_else(|| OsString::from(&paths[0]));
                Node { name, size: 0, children: Vec::new(), aggregated: false }
            }
        }
    } else {
        // Multi path: root is <collection>
        let mut children = Vec::new();
        let mut total_size = 0u64;
        for p in &paths {
            // For collection mode, use the path as given (not just file_name)
            // Actually, from observed output, it uses just the basename
            if let Some(n) = build_node(p, depth_limit, &opts, 0) {
                total_size += n.size;
                children.push(n);
            }
        }
        // In collection mode children are NOT sorted by size
        // Based on observation: "test4 test5 test6" outputs test4, test5, test6 in the order given
        // Actually let me re-examine... /tmp /tmp/test1 showed tmp first then test1 (first arg first).
        Node {
            name: OsString::from("<collection>"),
            size: total_size,
            children,
            aggregated: false,
        }
    };

    let mut out = String::new();
    let mut prefix_chain: Vec<bool> = Vec::new();
    let mut ancestor_widths: Vec<usize> = Vec::new();
    render_node(&root_node, 0, false, &mut prefix_chain, &mut ancestor_widths, 0, BAR_WIDTH, &opts, &mut out, true);

    print!("{}", out);
    io::stdout().flush().ok();
    ExitCode::from(0)
}
