fn parse_size(s: &str) -> Option<u64> {
    if s.is_empty() {
        return None;
    }
    let bytes = s.as_bytes();
    let mut num_end = 0;
    while num_end < bytes.len() && bytes[num_end].is_ascii_digit() {
        num_end += 1;
    }
    if num_end == 0 {
        return None;
    }
    let num_str = &s[..num_end];
    let num: u64 = num_str.parse().ok()?;
    let rest = &s[num_end..];
    // Allow trailing whitespace
    let rest_trimmed = rest.trim_end();
    let mult: u64 = match rest_trimmed {
        "" => 1,
        "k" | "K" => 1024,
        "m" | "M" => 1024 * 1024,
        "g" | "G" => 1024 * 1024 * 1024,
        "t" | "T" => 1024u64 * 1024 * 1024 * 1024,
        s if s.len() == 1 => 1, // any single char allowed, acts like bytes
        _ => return None,
    };
    Some(num.saturating_mul(mult))
}

fn parse_depth(s: &str) -> Option<usize> {
    s.parse::<usize>().ok()
}

// Parse CLI arguments. Returns Ok((opts, prog_name)) or Err(exit_code)
