                                got_a = true;
                            }
                            None => {
                                eprintln!("invalid argument '{}'", v);
                                return Err((1, None));
                            }
                        }
                    } else {
                        opts.aggr = Some(default_aggr);
                        got_a = true;
                    }
                }
                "summary" => {
                    got_d = true;
                    got_a = true;
                    opts.depth = 1;
                    opts.aggr = Some(default_aggr);
                }
                "usage" => opts.usage = true,
