                    'A' => { opts.ascii = true; ci += 1; }
                    'h' => {
                        print_usage(&prog);
                        return Err((0, None));
                    }
                    'v' => {
                        return Err((0, Some(format!("dutree version {}", VERSION))));
                    }
                    _ => {
                        print_usage(&prog);
                        eprintln!("Unrecognized option: '{}'", c);
                        return Err((1, None));
                    }
                }
            }
        } else {
            opts.paths.push(PathBuf::from(a));
        }
    }
    Ok(opts)
}

#[derive(Debug)]
struct Node {
    name: OsString,
    size: u64,
    children: Vec<Node>,
}

fn size_for_entry(meta: &fs::Metadata, usage: bool) -> u64 {
    if usage {
        (meta.blocks() as u64) * 512
    } else {
        meta.len()
    }
}

fn is_hidden(name: &OsStr) -> bool {
    let b = name.as_bytes();
    !b.is_empty() && b[0] == b'.'
}

fn basename_of(path: &Path) -> OsString {
    if let Some(n) = path.file_name() {
        return OsString::from(n);
    }
    // For paths like "/" or ".", use the full path
    // For "." specifically, resolve to absolute
    if path.as_os_str() == OsStr::new(".") {
        if let Ok(cwd) = env::current_dir() {
            if let Some(n) = cwd.file_name() {
                return OsString::from(n);
            }
            return OsString::from(&cwd);
        }
    }
    OsString::from(path)
}

fn build_node(path: &Path, depth_limit: usize, opts: &Opts, current_depth: usize, use_basename: bool) -> Option<Node> {
    let meta = fs::symlink_metadata(path).ok()?;
    let name = if use_basename {
        basename_of(path)
    } else {
        path.file_name().map(OsString::from).unwrap_or_else(|| OsString::from(path))
    };

    if opts.excludes.iter().any(|x| x == &name) {
        return None;
    }
    if opts.no_hidden && is_hidden(&name) {
        return None;
    }

    if meta.is_dir() && !meta.file_type().is_symlink() {
        if opts.files_only && current_depth > 0 {
            // files-only: skip directories EXCEPT the root directory
            // Actually from observation, -f skips subdirectories but shows files at root
            // Let me handle this in traversal
            return None;
        }
        let mut total_size = size_for_entry(&meta, opts.usage);
        let mut children: Vec<Node> = Vec::new();

        if let Ok(entries) = fs::read_dir(path) {
            for entry in entries.flatten() {
                let ent_path = entry.path();
                // When computing sizes, we recurse fully (ignore depth for size)
                if let Some(child) = build_node(&ent_path, depth_limit, opts, current_depth + 1, false) {
                    total_size += child.size;
                    children.push(child);
                }
            }
        }

        children.sort_by(|a, b| b.size.cmp(&a.size));

        if let Some(thresh) = opts.aggr {
            let mut kept: Vec<Node> = Vec::new();
            let mut agg_size: u64 = 0;
            let mut has_agg = false;
            for c in children {
                if c.size < thresh {
                    agg_size += c.size;
                    has_agg = true;
                } else {
                    kept.push(c);
                }
            }
            if has_agg && agg_size > 0 {
                kept.push(Node {
                    name: OsString::from("<aggregated>"),
                    size: agg_size,
                    children: Vec::new(),
                });
            }
            children = kept;
        }

        if current_depth >= depth_limit {
            for c in children.iter_mut() {
                c.children.clear();
            }
        }

        return Some(Node { name, size: total_size, children });
    } else {
        let size = size_for_entry(&meta, opts.usage);
        return Some(Node { name, size, children: Vec::new() });
    }
}

fn format_size(size: u64, bytes_mode: bool) -> String {
    if bytes_mode {
        return format!("{} B", size);
    }
    if size < 1024 {
        return format!("{} B", size);
    }
    let units = ["KiB", "MiB", "GiB", "TiB"];
    let mut value = size as f64 / 1024.0;
    let mut unit_idx = 0;
    while unit_idx < units.len() - 1 && value >= 1024.0 {
        value /= 1024.0;
        unit_idx += 1;
    }
    format!("{:.2} {}", value, units[unit_idx])
}

fn compute_bar_width(size: u64, parent_width: usize, scale_size: u64) -> usize {
    if scale_size == 0 || size == 0 {
        return 0;
    }
    let num = (size as u128) * ((parent_width as u128) + 1);
    if num <= scale_size as u128 {
        return 0;
    }
    let w = ((num - scale_size as u128) / (scale_size as u128)) as usize;
    if w > parent_width { parent_width } else { w }
}

fn render_bar(own_width: usize, ancestor_widths: &[usize], ascii: bool) -> String {
    let mut out = String::new();
    out.push(' ');
    let mut bar: Vec<char> = vec![' '; BAR_WIDTH];

    let (shade_widths, merged_own_width): (Vec<usize>, usize) = if ancestor_widths.len() <= MAX_SHADE_DEPTH {
        (ancestor_widths.to_vec(), own_width)
    } else {
        let shades = ancestor_widths[..MAX_SHADE_DEPTH].to_vec();
        let merged = ancestor_widths[MAX_SHADE_DEPTH];
        (shades, merged)
    };

    let shade_chars = if ascii {
        ['#', '#', '#']
    } else {
        ['░', '▒', '▓']
    };
    let full_char = if ascii { '#' } else { '█' };

    let mut filled_width = 0usize;
    for _ in 0..merged_own_width {
        if filled_width < BAR_WIDTH {
            bar[BAR_WIDTH - 1 - filled_width] = full_char;
            filled_width += 1;
        }
    }

    let mut inner_width = merged_own_width;
    for (i, &outer_width) in shade_widths.iter().enumerate().rev() {
        if outer_width > inner_width {
            let region_width = outer_width - inner_width;
            let ch = shade_chars[i];
            for _ in 0..region_width {
                if filled_width < BAR_WIDTH {
                    bar[BAR_WIDTH - 1 - filled_width] = ch;
                    filled_width += 1;
                }
            }
        }
        inner_width = outer_width;
    }

    for c in &bar {
        out.push(*c);
    }
    out
}

fn truncate_name(name: &str, max_width: usize) -> String {
    let count = name.chars().count();
    if count <= max_width {
        name.to_string()
    } else {
        name.chars().take(max_width).collect::<String>()
    }
}

// For a node at some level, render it and its descendants.
// parent_scale: the size to scale bars against (max_sibling for top-level, parent_size for nested)
// parent_bar_width: the width of the parent's bar (32 for conceptual root-level)
// parent_actual_size: the actual parent size (for percentage)
fn render_subtree(
    node: &Node,
    prefix_chain: &mut Vec<bool>,
    ancestor_widths: &mut Vec<usize>,
    parent_scale: u64,
    parent_bar_width: usize,
    parent_actual_size: u64,
    is_last: bool,
    opts: &Opts,
    out: &mut String,
) {
    // Build tree prefix
    let mut prefix = String::new();
    if !prefix_chain.is_empty() {
        for i in 0..prefix_chain.len() - 1 {
            if prefix_chain[i] {
                prefix.push_str("   ");
            } else {
                prefix.push_str("│  ");
            }
        }
        if is_last {
            prefix.push_str("└─ ");
        } else {
            prefix.push_str("├─ ");
        }
    }

    let prefix_width = prefix.chars().count();
    let name_str = node.name.to_string_lossy().to_string();
    let name_space = NAME_FIELD_WIDTH.saturating_sub(prefix_width);
    let name_truncated = if name_space > 0 {
        let max_name_len = name_space.saturating_sub(1);
        truncate_name(&name_str, max_name_len)
    } else {
        String::new()
    };
    let name_padding = name_space.saturating_sub(name_truncated.chars().count());

    let own_width = compute_bar_width(node.size, parent_bar_width, parent_scale);

    let bar_str = render_bar(own_width, ancestor_widths, opts.ascii);

    let pct: u64 = if parent_actual_size == 0 { 0 } else {
        let v = (node.size as u128) * 100 / (parent_actual_size as u128);
        v as u64
    };

    let size_str = format_size(node.size, opts.bytes);

    out.push_str(&prefix);
    out.push_str(&name_truncated);
    for _ in 0..name_padding {
        out.push(' ');
    }
    out.push('│');
    out.push_str(&bar_str);
    out.push('│');
    out.push_str(&format!("{:>4}%{:>14}", pct, size_str));
    out.push('\n');

    if !node.children.is_empty() {
        ancestor_widths.push(own_width);
        for (i, child) in node.children.iter().enumerate() {
            let last = i == node.children.len() - 1;
            prefix_chain.push(last);
            // For nested: scale by parent's actual size, bar width = own_width
            render_subtree(child, prefix_chain, ancestor_widths, node.size, own_width, node.size, last, opts, out);
            prefix_chain.pop();
        }
        ancestor_widths.pop();
    }
}

fn render_root(node: &Node, opts: &Opts, out: &mut String) {
    out.push_str(&format!("[ {} {} ]\n", node.name.to_string_lossy(), format_size(node.size, opts.bytes)));
    if node.children.is_empty() {
        return;
    }
    // For top-level children: bar scale = max_sibling_size, parent_bar_width = 32, parent_actual_size = root's size
    let max_sib = node.children.iter().map(|c| c.size).max().unwrap_or(1);
    let mut prefix_chain: Vec<bool> = Vec::new();
    let mut ancestor_widths: Vec<usize> = Vec::new();
    for (i, child) in node.children.iter().enumerate() {
        let last = i == node.children.len() - 1;
        prefix_chain.push(last);
        render_subtree(child, &mut prefix_chain, &mut ancestor_widths, max_sib, BAR_WIDTH, node.size, last, opts, out);
        prefix_chain.pop();
    }
}

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let opts = match parse_args(argv) {
        Ok(o) => o,
        Err((code, msg)) => {
            if let Some(m) = msg {
                println!("{}", m);
            }
            return ExitCode::from(code as u8);
        }
    };

    let paths = if opts.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        opts.paths.clone()
    };

    for p in &paths {
        match fs::symlink_metadata(p) {
            Ok(_) => {}
            Err(_) => {
                println!("path {} doesn't exist", p.display());
                return ExitCode::from(1);
            }
        }
    }

    let depth_limit = opts.depth;

    let root_node: Node = if paths.len() == 1 {
        match build_node(&paths[0], depth_limit, &opts, 0, true) {
            Some(n) => n,
            None => {
                let name = basename_of(&paths[0]);
                Node { name, size: 0, children: Vec::new() }
            }
        }
    } else {
        let mut children = Vec::new();
        let mut total_size = 0u64;
        for p in &paths {
            if let Some(n) = build_node(p, depth_limit, &opts, 0, true) {
                total_size += n.size;
                children.push(n);
            }
        }
        Node {
            name: OsString::from("<collection>"),
            size: total_size,
            children,
        }
    };

    let mut out = String::new();
    render_root(&root_node, &opts, &mut out);

    print!("{}", out);
    io::stdout().flush().ok();
    ExitCode::from(0)
}
